import{_ as c,C as n,o as s,c as i,aj as a,E as d,j as e,a as r}from"./framework.js";const f=JSON.parse('{"title":"货币 | Cms / Commerce | Documentation","description":"配置站点 默认货币 与 附加货币 及相对默认币的 汇率，用于多币种展示与换算。购物车 / 订单 在启用多币时可切换试算币种；商品与运费金额均以默认货币为基准，其它币种按汇率折算。数据写入 Commerce settings（currencyCode、currencySymbol、currencies[]），与 设置 中其它全局项并列，但 默认货币在本页维护。","frontmatter":{"title":"货币 | Cms / Commerce | Documentation","description":"配置站点 默认货币 与 附加货币 及相对默认币的 汇率，用于多币种展示与换算。购物车 / 订单 在启用多币时可切换试算币种；商品与运费金额均以默认货币为基准，其它币种按汇率折算。数据写入 Commerce settings（currencyCode、currencySymbol、currencies[]），与 设置 中其它全局项并列，但 默认货币在本页维护。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/commerce/currencies.html"}]]},"headers":[],"relativePath":"zh/cms/commerce/currencies.md","filePath":"cms/commerce/currencies.md","lastUpdated":1780453400000}'),l={name:"zh/cms/commerce/currencies.md"};function h(m,t,g,u,b,p){const o=n("DocImage");return s(),i("div",null,[t[0]||(t[0]=a('<h1 id="货币" tabindex="-1">货币 <a class="header-anchor" href="#货币" aria-label="Permalink to &quot;货币&quot;">​</a></h1><blockquote><p>菜单：<strong>电商 → 货币</strong><br> 深链：<code>/_Admin/commerce/currencies?SiteId={站点GUID}</code></p></blockquote><p>配置站点 <strong>默认货币</strong> 与 <strong>附加货币</strong> 及相对默认币的 <strong>汇率</strong>，用于多币种展示与换算。<a href="./carts.html">购物车</a> / <a href="./orders.html">订单</a> 在启用多币时可切换试算币种；商品与运费金额均以默认货币为基准，其它币种按汇率折算。数据写入 Commerce <code>settings</code>（<code>currencyCode</code>、<code>currencySymbol</code>、<code>currencies[]</code>），与 <a href="./settings.html">设置</a> 中其它全局项并列，但 <strong>默认货币在本页维护</strong>。</p><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选 <strong>电商 → 货币</strong>（及父级 <strong>电商</strong>）。</li><li>左侧 <strong>电商 → 货币</strong>。</li></ol><h2 id="列表页" tabindex="-1">列表页 <a class="header-anchor" href="#列表页" aria-label="Permalink to &quot;列表页&quot;">​</a></h2><p>路径：<code>/_Admin/commerce/currencies?SiteId=...</code></p><h3 id="默认货币" tabindex="-1">默认货币 <a class="header-anchor" href="#默认货币" aria-label="Permalink to &quot;默认货币&quot;">​</a></h3><p>页右上 <strong>默认货币</strong> 下拉：从系统货币库选择 <code>currencyCode</code>（选项形如 <code>USD - 美元 - $</code>）。切换时若已配置附加货币，会 <strong>确认提示</strong>；确认后将 <strong>清空附加货币列表</strong> 并更新默认符号，再保存 <code>settings</code>。</p><div class="warning custom-block"><p class="custom-block-title">切换默认货币</p><p>变更默认货币会移除当前已添加的 <strong>全部附加货币</strong> 配置，需重新添加并设置汇率。操作前请确认对历史订单展示与前台多币的影响。</p></div><h3 id="表格与操作" tabindex="-1">表格与操作 <a class="header-anchor" href="#表格与操作" aria-label="Permalink to &quot;表格与操作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>列 / 操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>代码</strong></td><td>ISO 式货币代码，如 <code>USD</code>、<code>CNY</code></td></tr><tr><td><strong>符号</strong></td><td>展示用符号</td></tr><tr><td><strong>名称</strong></td><td>本地化名称（<code>nameNative</code>）</td></tr><tr><td><strong>汇率</strong></td><td>相对 <strong>默认货币</strong> 的 <code>exchangeRate</code>，列表显示 6 位小数</td></tr><tr><td><strong>自动更新</strong></td><td>是否从服务端拉取最新汇率（<code>autoUpdate</code>）</td></tr><tr><td><strong>添加货币</strong></td><td>下拉：列出尚未添加且非默认的货币；选中后拉取 <code>getRate(默认, 目标)</code> 作为初始汇率并打开 <a href="#添加--编辑货币弹窗">编辑弹窗</a></td></tr><tr><td><strong>编辑</strong></td><td>行内铅笔，修改汇率与自动更新</td></tr><tr><td><strong>批量删除</strong></td><td>勾选附加货币行 → <strong>删除</strong> → 从 <code>settings.currencies</code> 移除并保存（默认货币行不可删）</td></tr></tbody></table>',12)),d(o,{src:"/cms/commerce/currencies-list.png",alt:"货币列表：添加货币、默认货币下拉与汇率表",width:"1120"}),t[1]||(t[1]=e("h3",{id:"添加-编辑货币弹窗",tabindex:"-1"},[r("添加 / 编辑货币弹窗 "),e("a",{class:"header-anchor",href:"#添加-编辑货币弹窗","aria-label":'Permalink to "添加 / 编辑货币弹窗"'},"​")],-1)),t[2]||(t[2]=e("p",null,[r("从 "),e("strong",null,"添加货币"),r(" 或行内 "),e("strong",null,"编辑"),r(" 打开（列表页内弹窗，不单独路由）。")],-1)),d(o,{src:"/cms/commerce/currencies-edit-dialog.png",alt:"编辑货币弹窗：代码、汇率与自动更新",width:"720"}),t[3]||(t[3]=a('<table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>代码</strong></td><td>只读，与所选货币一致</td></tr><tr><td><strong>汇率</strong></td><td>数字，精度 6 位，最小 <code>0.000001</code>；开启 <strong>自动更新</strong> 时禁用人工输入</td></tr><tr><td><strong>自动更新</strong></td><td>开启后由系统按默认货币定期更新汇率（保存至 <code>settings.currencies</code>）</td></tr></tbody></table><p>确认 <strong>保存</strong> 写入站点设置并刷新列表；<strong>取消</strong> 关闭弹窗。</p><h2 id="与其它模块的关系" tabindex="-1">与其它模块的关系 <a class="header-anchor" href="#与其它模块的关系" aria-label="Permalink to &quot;与其它模块的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>说明</th></tr></thead><tbody><tr><td><a href="./carts.html">购物车</a> / <a href="./orders.html">订单</a></td><td>存在附加货币时，新建/编辑/结账页右上可出现币种切换，试算使用对应 <code>exchangeRate</code></td></tr><tr><td><a href="./shippings.html">配送</a></td><td>基础运费等单位后缀为当前默认 <code>currencyCode</code></td></tr><tr><td><a href="./settings.html">设置</a></td><td>重量单位、支付方式、自定义字段等；默认货币以本页为准</td></tr></tbody></table><p>脚本 API：<a href="/kb-docs/zh/api/commerce/currency.html">k.commerce.currency</a>。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./settings.html">设置</a></li><li><a href="./orders.html">订单</a></li><li><a href="/kb-docs/zh/api/commerce/currency.html">k.commerce.currency</a></li></ul>',7))])}const y=c(l,[["render",h]]);export{f as __pageData,y as default};
